  forall (cur : Z) rax ra sp gp tp t0 t1 t2 a0x a6x a7x s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6 (j8 : list byte)
    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (itv fst La : Z),
  tincr_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v s7v ra j8 A W lo wbs itv fst La -> tokit_pure sp A W lo wbs fst La ->
  evt asegs (tokit_post_c (TokItCells 0 0 La La La) (Some A) ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc A W lo wbs m)
    (MS (tincr_regs rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 a0x La a6x a7x cur A s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

Local Ltac tincr_end_tac :=
  unfold tincr_end_stmt;
  intros cur rax ra sp gp tp t0 t1 t2 a0x a6x a7x s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6 j8 F fc m m1 A W lo wbs itv fst La;
  intros CTX PURE; pose proof PURE as PURE';
  destruct CTX as (FR & V & OBJ & WIN & ST & MU & WM & MI & SD);
  destruct PURE' as (HLA & LA64 & FST & SEPW & LO & CEIL & SEPA & SEPS & AL);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aobj_pos _ _ _ (proj1 (proj2 SD))) as (A0 & _ & AHI);
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPW; hydeL SEPA; hydeL SEPS; hydeL AL;
  unfold TokItCells, SZ_TOKIT, TOKIT_STACK, AINTRIN_STACK, AAPP_HI in *;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold tincr_regs, wz; rewrite ASHADOW_BASE_val;
  (* [comment removed for export] *)
  tk_ochk SD MU WM CEIL A 16 AL ltac:(idtac; step);
  st1;
  tk_ochk SD MU WM CEIL A 24 AL ltac:(idtac; step);
  st1;
  eapply tincr_epi; [exact FR| | exact WIN| exact ST| exact MU| exact WM| exact MI| exact SD| exact PURE];
  apply tokit_join0; [exact V| close_cells OBJ].

