(* [comment removed for export] *)
Lemma tincr_tok : forall (k i j : nat) (itv : Z) rax ra sp gp tp t0 t1 t2 a1x a5x a6x a7x s7x
    s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6 (j8 : list byte)
    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (Fi La : Z),
  (length wbs - j = k)%nat -> (i < j)%nat -> (j <= length wbs)%nat ->
  tincr_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v s7v ra j8 A W lo wbs itv Fi La -> tokit_pure sp A W lo wbs Fi La ->
  evt asegs (tokit_post_c (TokItCells (W + Z.of_nat i) (Z.of_nat (j - i + tspan (skipn j (zbytes wbs))))
                             (W + Z.of_nat (j + tspan (skipn j (zbytes wbs)))) Fi La) (Some A)
               ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc A W lo wbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz A) (wz (A + 16)) (wz (W + Z.of_nat j)) a1x (wz La)
              (wz 0x28b80) (wz (W + Z.of_nat j)) a5x a6x a7x
              (wz (W + Z.of_nat i)) (wz (A + 24)) (wz ASHADOW_BASE) (Z_to_bv 64 (Z.shiftr (A + 16) 3 + 2147450880))
              (Z_to_bv 64 (Z.shiftr (A + 24) 3 + 2147450880)) s7x s8 s9 s10 s11 t3 t4 t5 t6)
