    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (Fi La : Z),
  (2 * (length wbs - i) + (if ph then 1 else 0) < mu)%nat ->
  (i <= length wbs)%nat -> (ph = true -> (i < length wbs)%nat) ->
  (ph = false -> forall b, nth_error wbs i = Some b -> is_ws (zb b) = false) ->
  tincr_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v s7v ra j8 A W lo wbs (W + Z.of_nat i) Fi La -> tokit_pure sp A W lo wbs Fi La ->
