               ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc A W lo wbs m)
    (MS (tincr_regs rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                    (if ph then wz (W + Z.of_nat i) else a0x) La (wz (if nc then 1 else 0)) a7x
                    (W + Z.of_nat i) A s7x s8 s9 s10 s11 t3 t4 t5 t6)
