Lemma b2z_xor_nez : forall x y, 0 <= x -> 0 <= y -> Z.b2z (0 <? Z.lxor x y) = (if negb (x =? y) then 1 else 0).
Proof.
  intros x y Hx Hy. pose proof (proj2 (Z.lxor_nonneg x y) ltac:(lia)) as NN.
  destruct (Z.eqb_spec x y) as [<-|NE].
  - rewrite Z.lxor_nilpotent. reflexivity.
  - cbn [negb]. assert (NZ : Z.lxor x y <> 0) by (intros E; apply NE; apply Z.lxor_eq_0_iff; exact E).
    replace (0 <? Z.lxor x y) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity.
Qed.

Lemma tokit_incr_post_c : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A it fst La W lo wbs m ms,
  tokit_post_c (tokit_cells_after (tok_next (negb (it =? fst)) (tok_suffix W it wbs)) it La) (Some A)
    ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A W lo wbs m ms ->
  tokit_incr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A it fst La W lo wbs m ms.
Proof.
  intros until ms. intros (t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m' & E & A0 & K).
  rewrite (A0 A eq_refl) in E.
  exists t0, t1, t2, a1, a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, m'. split; [exact E| exact K].
Qed.

